  put(18, 6, 11, B.block("bookshelf"));
  put(18, 7, 11, B.block("bookshelf"));

  // ceiling lanterns over the room: bed foot and the east half, so the floor is lit everywhere
  put(14, 8, 12, B.lantern(true));
  put(17, 8, 12, B.lantern(true));
}

